// ConfirmPair is the resolver for the confirmPair field.
func (r *mutationResolver) ConfirmPair(ctx context.Context, user string) (model.PairState, error) {
	d, err := r.caller(ctx)
	if err != nil {
		return "", err
	}
	if r.Users.Find(user) == nil {
		return "", refusal(relay.UnknownUser)
	}
	if r.Relay.Book.Blocked(d.User, user) {
		return "", refusal(relay.Blocked)
	}
	already := r.Relay.Book.Paired(d.User, user)
	paired, err := r.Relay.Book.Confirm(d.User, user)
	if errors.Is(err, contacts.ErrNoPairing) {
		return "", coded(CodeNoPairing, "%v", err)
	}
	if err != nil {
		return "", err
	}
	if !paired {
		return model.PairStateWaiting, nil
	}
	if !already {
		log.Printf("Paired %s and %s", d.User, user)
		r.Relay.Announce(pb.Envelope_PAIRED, user, nil, d.User)
		r.Relay.Announce(pb.Envelope_PAIRED, d.User, nil, user)
	}
	return model.PairStatePaired, nil
}

// Unpair is the resolver for the unpair field.
func (r *mutationResolver) Unpair(ctx context.Context, user string) (bool, error) {
	d, err := r.caller(ctx)
	if err != nil {
		return false, err
	}
	had, err := r.Relay.Book.Unpair(d.User, user)
	if had {
		log.Printf("%s unpaired %s", d.User, user)
		if !r.Relay.ShareGroup(d.User, user) {
			r.Relay.LeaveRoom(livekit.PairRoom(d.User, user), user)
			r.Relay.LeaveRoom(livekit.PairRoom(d.User, user), d.User)
			r.Relay.LeaveCalls(user, d.User, "")
			r.Relay.LeaveCalls(d.User, user, "")
		}
	}
	return had, err
}

// Block is the resolver for the block field.
func (r *mutationResolver) Block(ctx context.Context, user string) (bool, error) {
	d, err := r.caller(ctx)
	if err != nil {
		return false, err
	}
	if r.Users.Find(user) == nil {
		return false, refusal(relay.UnknownUser)
	}
	if user == d.User {
		return false, fmt.Errorf("a user can't block itself")
	}
	if err := r.Relay.Book.Block(d.User, user); err != nil {
		return false, err
	}
	log.Printf("%s blocked %s", d.User, user)
	r.Relay.LeaveRoom(livekit.PairRoom(d.User, user), user)
	r.Relay.LeaveRoom(livekit.PairRoom(d.User, user), d.User)
	r.Relay.LeaveCalls(user, d.User, "")
	r.Relay.LeaveCalls(d.User, user, "")
	return true, nil
}

