// Devices is the resolver for the devices field.
func (r *queryResolver) Devices(ctx context.Context) ([]*model.OwnDevice, error) {
	d, err := r.caller(ctx)
	if err != nil {
		return nil, err
	}
	keyed, err := r.Relay.Store.KeyedDevices(d.User)
	if err != nil {
		return nil, err
	}
	enrolled := r.Relay.EnrolledDevices(d.User)
	result := []*model.OwnDevice{}
	for _, device := range r.Enrollment.Registry.List(d.User) {
		// The newest certificate of each number that is enrolled (a renewal keeps the number).
		if !slices.Contains(enrolled, device.DeviceNumber) || r.Enrollment.Registry.IsRevoked(device.Serial) {
			continue
		}
		own := &model.OwnDevice{DeviceNumber: device.DeviceNumber, Name: device.Name, RegisteredAt: device.RegisteredAt,
			LastSeenAt: device.LastSeenAt, KeyProtection: keyProtection(device.KeyProtection),
			Current: device.DeviceNumber == d.Number}
		if registration, ok := keyed[device.DeviceNumber]; ok {
			own.RegistrationID = &registration
		}
		if i := slices.IndexFunc(result, func(o *model.OwnDevice) bool { return o.DeviceNumber == device.DeviceNumber }); i >= 0 {
			result[i] = own
		} else {
			result = append(result, own)
		}
	}
	slices.SortFunc(result, func(a, b *model.OwnDevice) int { return a.DeviceNumber - b.DeviceNumber })
	return result, nil
}
